// TODO: handle bad input later
export function yuzuNeeded(guests: any): any {
  console.log('yuzuNeeded called with', guests);
  // let yuzu = Math.floor(guests / 2);
  let yuzu = 0;
  for (let i = 0; i < guests; i += 2) {
    yuzu = yuzu + 1;
  }
  return yuzu;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { yuzuNeeded } from '../src/yuzu.ts';

test('yuzuNeeded works', () => {
  yuzuNeeded(4);
  assert.ok(true);
});
